#include "library.h"

long long mod = (1LL << 32);

template <typename T>
T extGcd(T a, T b, T& x, T& y) {
	if (b == 0) {
		x = 1;
		y = 0;
		return a;
	}

	T g = extGcd(b, a % b, y, x);
	y -= a / b * x;
	return g;
}

template <typename T>
T modInv(T a, T m) {
	T x, y;
	extGcd(a, m, x, y);
	return ((x % m) + m) % m;
}

unsigned C[150];
int n, p, q;

void solve() {
	scanf("%d %d %d", &n, &p, &q);
	if (p > n - 1) p = n - 1;

	for (int pp = 0; pp <= p; pp++) {
		C[pp] = 1;
		int tw = 0;

		for (int i = n; i > n - pp; i--) {
			int ti = i;
			while (ti % 2 == 0) {
				ti /= 2;
				tw++;
			}
			C[pp] = (C[pp] * 1LL * ti) % mod;
		}

		for (int i = 1; i <= pp; i++) {
			int ti = i;
			while (ti % 2 == 0) {
				ti /= 2;
				tw--;
			}
			C[pp] = (C[pp] * 1LL *
			         modInv(static_cast<long long>(ti), mod)) % mod;
		}

		for (int i = 0; i < tw; i++) {
			C[pp] = (C[pp] * 2LL) % mod;
		}
	}

	unsigned ans = 0;

	for (int i = 1; i <= q; i++) {
		unsigned curr = 0;
		unsigned pot = 1;

		for (int pp = 0; pp <= p; pp++) {
			curr = (curr + pot * C[pp]) % mod;
			pot *= i;
		}

		ans ^= i * curr;
	}

	printf("%u\n", ans);
}

